def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(cells)

    template = max(components, key=len)
    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    patch = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    center_r, center_c = (r1 - r0) // 2, (c1 - c0) // 2

    out = [row[:] for row in grid]
    for comp in components:
        if comp is template or len(comp) != 1:
            continue
        mr, mc = comp[0]
        top, left = mr - center_r, mc - center_c
        for dr, row in enumerate(patch):
            for dc, value in enumerate(row):
                rr, cc = top + dr, left + dc
                # Treat the motif's background-colored cells as transparent.
                if 0 <= rr < h and 0 <= cc < w and value != bg:
                    out[rr][cc] = value
    return out
